import java.util.*;
import java.io.*;

public class Main {
    static final long P = 1000000007;

    static class FiniteField {
        long x;

        FiniteField(long x) {
            if (x > P || x < 0) {
                System.err.println("Invalid FiniteField!");
                System.exit(1);
            }
            this.x = x;
        }

        FiniteField() {
            this.x = 0;
        }

        long Value() {
            return x;
        }

        FiniteField plus(FiniteField o) {
            return new FiniteField((x + o.x) % P);
        }

        FiniteField minus(FiniteField o) {
            return new FiniteField((x + P - o.x) % P);
        }

        FiniteField times(FiniteField o) {
            return new FiniteField((x * o.x) % P);
        }

        FiniteField divide(FiniteField o) {
            return new FiniteField((x * modInverse(o.x, P)) % P);
        }

        private long modInverse(long a, long m) {
            long m0 = m, t, q;
            long x0 = 0, x1 = 1;
            if (m == 1)
                return 0;
            while (a > 1) {
                q = a / m;
                t = m;
                m = a % m;
                a = t;
                t = x0;
                x0 = x1 - q * x0;
                x1 = t;
            }
            if (x1 < 0)
                x1 += m0;
            return x1;
        }
    }

    static <T> List<List<T>> create2D(int d1, int d2, T val) {
        List<List<T>> res = new ArrayList<>();
        for (int i = 0; i < d1; i++) {
            List<T> row = new ArrayList<>(Collections.nCopies(d2, val));
            res.add(row);
        }
        return res;
    }

    static <T> List<List<List<T>>> create3D(int d1, int d2, int d3, T val) {
        List<List<List<T>>> res = new ArrayList<>();
        for (int i = 0; i < d1; i++) {
            res.add(create2D(d2, d3, val));
        }
        return res;
    }

    static <T> List<List<T>> matrixMultiply(List<List<T>> a, List<List<T>> b, java.util.function.BiFunction<T, T, T> add, java.util.function.BiFunction<T, T, T> mul, T zero) {
        int n = a.size();
        int m = a.get(0).size();
        int l = b.get(0).size();
        List<List<T>> result = create2D(n, l, zero);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < l; j++) {
                T sum = zero;
                for (int k = 0; k < m; k++) {
                    sum = add.apply(sum, mul.apply(a.get(i).get(k), b.get(k).get(j)));
                }
                result.get(i).set(j, sum);
            }
        }
        return result;
    }

    static <T> List<T> matrixVectorMultiply(List<List<T>> matrix, List<T> v, java.util.function.BiFunction<T, T, T> add, java.util.function.BiFunction<T, T, T> mul, T zero) {
        int n = matrix.size();
        int m = matrix.get(0).size();
        if (v.size() != m) {
            System.err.println("Dimension mismatch for matrix-vector multiplication!");
            System.exit(1);
        }
        List<T> res = new ArrayList<>(Collections.nCopies(n, zero));
        for (int i = 0; i < n; i++) {
            T sum = zero;
            for (int j = 0; j < m; j++) {
                sum = add.apply(sum, mul.apply(matrix.get(i).get(j), v.get(j)));
            }
            res.set(i, sum);
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int d = sc.nextInt();

        List<List<List<FiniteField>>> shifts = create3D(d, d + 1, d + 1, new FiniteField(0));
        for (int k = 0; k < d; k++) {
            for (int i = 0; i < d; i++) {
                shifts.get(k).get(i).set((i + k) % d, new FiniteField(1));
            }
            shifts.get(k).get(d).set(d, new FiniteField(1));
        }

        List<List<List<FiniteField>>> units = create3D(d, d + 1, d + 1, new FiniteField(0));
        for (int k = 0; k < d; k++) {
            for (int i = 0; i <= d; i++) {
                units.get(k).get(i).set(i, new FiniteField(1));
            }
            for (int i = 0; i <= d; i++) {
                units.get(k).get(k).set(i, new FiniteField(1));
            }
        }

        List<List<FiniteField>> identity = create2D(d + 1, d + 1, new FiniteField(0));
        for (int i = 0; i <= d; i++) {
            identity.get(i).set(i, new FiniteField(1));
        }

        Map<Long, List<List<FiniteField>>> cache = new HashMap<>();

        java.util.function.Function<Long, List<List<FiniteField>>> findMatrix = new java.util.function.Function<Long, List<List<FiniteField>>>() {
            public List<List<FiniteField>> apply(Long p) {
                if (cache.containsKey(p)) {
                    return cache.get(p);
                }
                List<List<FiniteField>> result;
                if (p <= d) {
                    result = create2D(d + 1, d + 1, new FiniteField(0));
                    for (int i = 0; i <= d; i++) {
                        result.get(i).set(i, new FiniteField(1));
                    }
                    for (int k = 0; k < p; k++) {
                        result = matrixMultiply(units.get(k), result, FiniteField::plus, FiniteField::times, new FiniteField(0));
                    }
                    cache.put(p, result);
                    return result;
                }
                long child_p = d;
                while ((p + child_p - 1) / child_p > d) {
                    child_p *= d;
                }
                List<List<FiniteField>> child = apply(child_p);
                result = child;
                long remaining_p = p;
                remaining_p -= child_p;
                for (int k = 1; k < d; k++) {
                    if (remaining_p >= child_p) {
                        result = matrixMultiply(shifts.get(d - k), result, FiniteField::plus, FiniteField::times, new FiniteField(0));
                        result = matrixMultiply(result, shifts.get(k), FiniteField::plus, FiniteField::times, new FiniteField(0));
                        result = matrixMultiply(result, child, FiniteField::plus, FiniteField::times, new FiniteField(0));
                        remaining_p -= child_p;
                    } else if (remaining_p > 0) {
                        List<List<FiniteField>> rem_matrix = apply(remaining_p);
                        result = matrixMultiply(shifts.get(d - k), result, FiniteField::plus, FiniteField::times, new FiniteField(0));
                        result = matrixMultiply(result, rem_matrix, FiniteField::plus, FiniteField::times, new FiniteField(0));
                        result = matrixMultiply(result, shifts.get(k), FiniteField::plus, FiniteField::times, new FiniteField(0));
                        remaining_p = 0;
                    } else {
                        break;
                    }
                }
                cache.put(p, result);
                return result;
            }
        };

        List<List<FiniteField>> matrix = findMatrix.apply(n);
        List<FiniteField> base_vector = new ArrayList<>(Collections.nCopies(d + 1, new FiniteField(0)));
        base_vector.set(d, new FiniteField(1));
        List<FiniteField> final_vector = matrixVectorMultiply(matrix, base_vector, FiniteField::plus, FiniteField::times, new FiniteField(0));
        FiniteField answer = new FiniteField(0);
        for (FiniteField val : final_vector) {
            answer = answer.plus(val);
        }
        System.out.println(answer.Value());
        sc.close();
    }
}
